// NO directive: server-safe. No hook, no context, no browser API, so every icon renders in a Server
// Component with zero client JavaScript (ARCHITECTURE.md §14.2). Hand-written; the per-icon modules
// under src/icons/ and src/brands/ are generated by scripts/generate.ts and only call these two
// functions, so the markup of all ~1,900 icons is decided here, once.
import type { ComponentPropsWithRef, JSX } from 'react';

/** The SVG elements Lucide draws with. */
export type IconTag = 'circle' | 'ellipse' | 'line' | 'path' | 'polygon' | 'polyline' | 'rect';

/** An icon's drawing: its child elements on the 24 × 24 viewBox, in paint order. */
export type IconNode = readonly (readonly [
  tag: IconTag,
  attributes: Readonly<Record<string, string>>,
])[];

interface BaseIconProps extends Omit<ComponentPropsWithRef<'svg'>, 'strokeWidth'> {
  /**
   * Width and height. The default follows the font size, so an icon fills the slot it is placed in
   * (Button and IconButton size their icon slots through `font-size`). Pass `20` for a standalone
   * 20 px icon.
   * @default '1em'
   */
  size?: number | string;
  /**
   * The accessible name. Without it (and without `aria-label` or `aria-labelledby`) the icon is
   * decorative: `aria-hidden`. With it, the icon is `role="img"` named by `aria-label`. An empty or
   * blank string counts as no name, so the icon stays decorative. A `<title>` child does not name
   * the icon (it stays hidden); use `label`.
   */
  label?: string;
}

/** Props of every stroke icon: the Lucide-shaped stroke contract of `@nizivo/icons` (§14.2). */
export interface IconProps extends BaseIconProps {
  /**
   * Stroke width in viewBox units (24 across). 1.92 renders 1.6 px at 20 px and 1.28 px at 16 px,
   * what Figma draws (§14.2, settled 7).
   * @default 1.92
   */
  strokeWidth?: number | string;
  /**
   * Keep the stroke at `strokeWidth` CSS pixels at every size (`vector-effect: non-scaling-stroke`),
   * whatever unit `size` uses. Pair it with `strokeWidth={1.6}`.
   * @default false
   */
  absoluteStrokeWidth?: boolean;
  /**
   * For a directional icon (`mirror.json`): set `false` to keep it unmirrored in right-to-left text.
   * Other icons ignore it.
   * @default true
   */
  mirror?: boolean;
}

/** Props of a filled brand glyph (`@nizivo/icons/brands/<name>`). */
export interface BrandIconProps extends Omit<
  BaseIconProps,
  'stroke' | 'strokeLinecap' | 'strokeLinejoin'
> {}

/** A string with something to read: `''` and whitespace name nothing (axe svg-img-alt). */
function filled(value: string | undefined): value is string {
  return value !== undefined && value.trim() !== '';
}

/** True when the consumer named the icon some way, so it must not be hidden from assistive tech. */
function isNamed(props: BaseIconProps): boolean {
  return filled(props.label) || filled(props['aria-label']) || filled(props['aria-labelledby']);
}

/** Renders a stroke icon. `mirrors` comes from `mirror.json` at generation time. */
export function renderIcon(props: IconProps, nodes: IconNode, mirrors?: true): JSX.Element {
  const {
    size = '1em',
    strokeWidth = 1.92,
    absoluteStrokeWidth = false,
    label,
    mirror = true,
    children,
    ...rest
  } = props;
  const named = isNamed(props);
  const vectorEffect = absoluteStrokeWidth ? 'non-scaling-stroke' : undefined;
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden={named ? undefined : true}
      role={named ? 'img' : undefined}
      aria-label={filled(label) ? label : undefined}
      data-mirror={mirrors && mirror ? 'rtl' : undefined}
      {...rest}
    >
      {nodes.map(([Tag, attributes], index) => (
        // The drawing is static, so the index is a stable key.
        // oxlint-disable-next-line react/no-array-index-key
        <Tag key={index} {...attributes} vectorEffect={vectorEffect} />
      ))}
      {children}
    </svg>
  );
}

/** Renders a filled brand glyph from one path. */
export function renderBrand(props: BrandIconProps, d: string): JSX.Element {
  const { size = '1em', label, children, ...rest } = props;
  const named = isNamed(props);
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="currentColor"
      aria-hidden={named ? undefined : true}
      role={named ? 'img' : undefined}
      aria-label={filled(label) ? label : undefined}
      {...rest}
    >
      <path d={d} />
      {children}
    </svg>
  );
}
